"""Phase 4.2 first milestone: actual physical activity and preserved world/clock contracts."""
import unittest
import test_living_world_integration as base
class LivingShipIntegration(base.LivingWorldIntegration):
 def test_existing_world_gains_private_activity_continuity_and_exact_reload(self):
  p=self.page();self.advance(p,120);s=self.snap(p);self.assertEqual(len(s['crew']),20);self.assertEqual(s['crewLife']['activityTick'],s['tick']);self.assertTrue(all(x.get('activity') for x in s['crewLife']['people'].values()));self.assertTrue(all(len(x.get('activityHistory',[]))<=16 for x in s['crewLife']['people'].values()));self.assertEqual(s['resourceAudit'],[]);self.assertEqual(s['knowledgeAudit'],[]);p.evaluate('__icarusSoak.save()');p.reload();self.assertEqual(self.snap(p),s)
 def test_real_week_boundary_preserves_shift_and_activities_without_world_reset(self):
  p=self.page();self.advance(p,5);before=self.snap(p);p.evaluate('__icarusSoak.realStart(Date.parse("2026-06-07T23:59Z"),"UTC")');p.evaluate('__icarusSoak.realAdvance(Date.parse("2026-06-08T00:01Z"))');after=self.snap(p);self.assertEqual(after['episode'],before['episode']+1);self.assertGreater(after['tick'],before['tick']);self.assertEqual([x['name'] for x in after['crew']],[x['name'] for x in before['crew']]);self.assertEqual({n:x['shift'] for n,x in after['crewLife']['people'].items()},{n:x['shift'] for n,x in before['crewLife']['people'].items()});self.assertEqual(after['resourceAudit'],[])
 def test_views_do_not_advance_activity_or_invent_progress(self):
  p=self.page();self.advance(p,10);before=self.snap(p);p.evaluate("ICARUSCommandUI.navigate('operations','watch')");p.evaluate('__icarusSoak.phase3("render")');p.set_viewport_size({'width':1280,'height':800});self.assertEqual(self.snap(p),before)
 def test_full_phase41_backup_import_retains_existing_crew_routines_and_history(self):
  import json
  from pathlib import Path
  donor=Path('/workspace/work/phase41_final_validation/campaigns/normal_1001/backup_1001_30.json');self.assertTrue(donor.exists(),'Genuine Phase 4.1 migration fixture is required');old=json.loads(donor.read_text())['state'];p=self.page();p.set_default_timeout(600000);p.on('dialog',lambda d:d.accept());p.locator('#backupfile').set_input_files(str(donor));p.wait_for_function('(tick)=>__icarusSoak.time()===tick',arg=old['tick']);s=self.snap(p);self.assertEqual(s['tick'],old['tick']);self.assertEqual([q['name'] for q in s['crew']],[q['name'] for q in old['crew']]);self.assertEqual(s['economy'],old['economy']);self.assertEqual(s['navigation'],old['navigation']);
  for name,person in old['crewLife']['people'].items():
   for key in ['memories','recent','decisions','lastSocial','peerAt','preferredWork']:self.assertEqual(s['crewLife']['people'][name][key],person[key])
  self.assertTrue(all(x.get('shift') for x in s['crewLife']['people'].values()));p.evaluate('__icarusSoak.save()');p.reload();self.assertEqual(self.snap(p),s)
 def test_private_social_memory_is_sourced_and_survives_reload_without_sol_access(self):
  p=self.page();self.configure(p,"""s.remoteCore.autonomyEnabled=false;for(const q of s.crew.slice(0,2)){q.room='A04';q.target='A04';q.route=[];q.nav=null;q.task='Seeking a conversation';q.goal=q.task;q.taskMinutes=50;q.social=15;q.energy=90;q.stress=50;q.maintenanceRoom=null;q.researchAssignment=null;q.emergencyId=null;}""");r=p.evaluate("__icarusSoak.phase3('talk',{from:'Frank Morrow',to:'Mara Chen'})");self.assertTrue(r['id']);s=self.snap(p);m=s['crewSocial']['people']['Frank Morrow']['memories'];self.assertEqual(m[-1]['sourceId'],r['id']);f=next(f for f in s['knowledge']['facts'].values() if f['sourceId']==r['id']);self.assertEqual(f['disclosure'],'private');self.assertNotIn(f['id'],s['knowledge']['actors']['SOL']['entries']);self.assertEqual(s['socialAudit'],[]);p.evaluate('__icarusSoak.save()');p.reload();self.assertEqual(self.snap(p),s)
 def test_optional_private_preferences_require_creator_and_do_not_invent_events(self):
  p=self.page();self.operations(p);self.assertEqual(p.get_by_text('PRIVATE RELATIONSHIP PREFERENCES / CREATOR',exact=True).count(),0);p.keyboard.press('Control+Shift+F12');self.deck(p,'personnel','roster');box=p.locator('#detail details').filter(has=p.get_by_text('PRIVATE RELATIONSHIP PREFERENCES / CREATOR',exact=True));box.locator('summary').click();before=self.snap(p);box.locator('input[type=checkbox]').check();box.locator('select').select_option('Mara Chen');box.locator('button').click();after=self.snap(p);self.assertTrue(after['crew'][0]['adult']);self.assertEqual(after['crew'][0]['romanticInterest'],['Mara Chen']);self.assertEqual(after['chronicle'],before['chronicle']);self.assertEqual(after['knowledge'],before['knowledge']);p.evaluate('__icarusSoak.save()');p.reload();self.assertEqual(self.snap(p),after);self.assertFalse(p.evaluate('ICARUSBridgeMode.creator'))
 def test_100_registered_20_active_crew_registry_remains_dormant_across_week_and_reload(self):
  p=self.page();names=['Reserve fixture '+str(i) for i in range(80)];r=p.evaluate("names=>__icarusSoak.knowledgeAction('event',{text:'Explicit test personnel manifest',people:['Frank Morrow'],data:{registeredCrew:names,fixture:true}})",names);registered=p.evaluate("a=>a.names.map(name=>__icarusSoak.phase42('register',{profile:{name,job:'Reserve'},sourceId:a.id}))",{'names':names,'id':r['id']});self.assertTrue(all(registered));self.advance(p,120);s=self.snap(p);self.assertEqual(len(s['crewSocial']['registry']),100);self.assertEqual(len(s['crew']),20);self.assertEqual(len(s['crewSocial']['people']),20);self.assertFalse(any(n in s['knowledge']['actors'] for n in names));self.assertEqual(s['socialAudit'],[]);p.evaluate('__icarusSoak.realStart(Date.parse("2026-06-07T23:59Z"),"UTC")');p.evaluate('__icarusSoak.realAdvance(Date.parse("2026-06-08T00:01Z"))');s=self.snap(p);self.assertEqual(len(s['crewSocial']['registry']),100);p.evaluate('__icarusSoak.save()');p.reload();self.assertEqual(self.snap(p),s)
 def test_real_cleanup_reduces_existing_debris_through_local_work_and_emits_actual_source(self):
  p=self.page();self.configure(p,"""s.remoteCore.autonomyEnabled=false;s.frontier.enabled=false;const q=s.crew[0];q.room='C05';q.target='C05';q.route=[];q.nav=null;q.task=q.goal='Clearing debris';q.taskMinutes=12;q.energy=90;q.hunger=10;q.stress=30;q.interaction=null;q.maintenanceRoom=null;q.emergencyId=null;s.physicalWorld.rooms.C05.debris=20;for(const other of s.crew.slice(1)){other.goal=other.task='Reviewing duty records';other.taskMinutes=999;}""");self.advance(p,12);s=self.snap(p);self.assertAlmostEqual(s['world']['physicalWorld']['rooms']['C05']['debris'],10.4,places=6);self.assertLess(s['crew'][0]['energy'],90);sources=[r for r in s['chronicle']['records'] if r['data'].get('activity')=='cleanup' and not r['data'].get('knowledgeDelivery')];self.assertEqual(len(sources),1);self.assertIn('Frank Morrow',sources[0]['people']);self.assertEqual(s['resourceAudit'],[]);self.assertEqual(s['socialAudit'],[])
 def test_uncertain_gossip_is_a_labeled_sol_claim_then_corrected_through_actual_contact(self):
  p=self.page();self.configure(p,"""s.remoteCore.autonomyEnabled=false;for(const q of s.crew.slice(0,2)){q.room=q.target='A04';q.route=[];q.nav=null;q.task=q.goal='Seeking a conversation';q.taskMinutes=50;q.social=10;q.energy=90;q.stress=80;q.maintenanceRoom=null;q.researchAssignment=null;q.emergencyId=null;}""")
  source=p.evaluate("__icarusSoak.knowledgeAction('event',{text:'Explicit uncertain mechanical-reading fixture',people:['Frank Morrow'],data:{uncertain:true,fixture:true}})");state=self.snap(p);fact=next(f for f in state['knowledge']['facts'].values() if f['sourceId']==source['id']);seed=p.evaluate("id=>{let seed=1;while(ICARUSUniverse.draw(seed,'interpretation:Frank Morrow:Mara Chen:'+id)>=.2)seed++;return seed;}",fact['id']);self.change(p,'s.universe.seed='+str(seed)+';')
  p.evaluate("__icarusSoak.phase3('talk',{from:'Frank Morrow',to:'Mara Chen'})");state=self.snap(p);claim=next(f for f in state['knowledge']['facts'].values() if f['kind']=='reported-claim');self.assertNotIn(fact['id'],state['knowledge']['actors']['Mara Chen']['entries']);self.assertNotIn('map',claim['data'])
  # At tick zero the established social channel legitimately also shares the original.
  p.evaluate("__icarusSoak.knowledgeAction('tick',{})");state=self.snap(p);self.assertIn(claim['id'],state['knowledge']['actors']['SOL']['entries']);received=next(r for r in state['chronicle']['records'] if r['id']==state['knowledge']['facts'][claim['id']]['publicationSourceId']);self.assertIn('UNVERIFIED CLAIM',received['message']);self.assertIn(fact['id'],state['knowledge']['actors']['Mara Chen']['entries']);self.assertEqual(state['knowledge']['actors']['Mara Chen']['entries'][claim['id']]['review']['sourceFactId'],fact['id']);self.assertEqual(state['knowledgeAudit'],[]);self.assertEqual(state['socialAudit'],[]);p.evaluate('__icarusSoak.save()');p.reload();self.assertEqual(self.snap(p),state)
if __name__=='__main__':unittest.main()
